inp = task_data['pairs'][0]['input']
H, W = len(inp), len(inp[0])
bg = 7  # Background color

print(f"Task input: {H}x{W}, background={bg}")
print("Non-background cells:")

# Find all non-bg cells
non_bg = []
for r in range(H):
    for c in range(W):
        v = inp[r][c]
        if v != bg:
            non_bg.append((r, c, v))
            print(f"  ({r:2d},{c:2d}): {v}")

print(f"\nTotal non-background: {len(non_bg)}")

# Apply the solve function
def solve(inp, bg=7):
    H, W = len(inp), len(inp[0])
    out = copy.deepcopy(inp)

    by_color = defaultdict(list)
    for r in range(H):
        for c in range(W):
            if inp[r][c] != bg:
                by_color[inp[r][c]].append((r, c))

    for color in sorted(by_color.keys()):
        cells = sorted(by_color[color])

        if len(cells) < 2:
            continue

        pairs_to_process = []
        for i in range(len(cells)):
            r1, c1 = cells[i]
            for j in range(i+1, len(cells)):
                r2, c2 = cells[j]
                dist_abs = abs(r1 - r2) + abs(c1 - c2)
                if dist_abs == 2:
                    if r1 - c1 == r2 - c2 or r1 + c1 == r2 + c2:
                        pairs_to_process.append(((r1, c1), (r2, c2)))

        if not pairs_to_process:
            continue

        for (r1, c1), (r2, c2) in pairs_to_process:
            color_val = inp[r1][c1]

            dr12 = r2 - r1
            dc12 = c2 - c1

            nr, nc = r1 + dr12 * -1, c1 + dc12 * -1
            dr_cell1, dc_cell1 = -dr12, -dc12
            while nr >= 0 and nr < H and nc >= 0 and nc < W:
                if out[nr][nc] != bg:
                    break
                if nr == r1 and nc == c1:
                    break
                out[nr][nc] = color_val
                nr += dr_cell1
                nc += dc_cell1

            nr, nc = r2 + dr12, c2 + dc12
            while nr >= 0 and nr < H and nc >= 0 and nc < W:
                if out[nr][nc] != bg:
                    break
                if nr == r2 and nc == c2:
                    break
                out[nr][nc] = color_val
                nr += dr12
                nc += dc12

    return out

out = solve(inp, bg)

# Generate output JSON
